(n, m) = map(int, input().split())
l = set(list(map(int, input().split())))
ans = []
for x in range(n + 1):
	(z, ct, b) = (1, 0, 0)
	while True:
		if z == 1 and ct != 0:
			break
		if b == m:
			break
		if z in l:
			b += 1
		if z + x <= n:
			z += x
		else:
			k = z + x
			z = k - n
		ct += 1
	if b == m:
		ans.append(ct)
print(min(ans))
